'use strict';
const assert=require('node:assert/strict');
const fs=require('node:fs');
const path=require('node:path');
const {chromium}=require('playwright');
const TEST_URL=process.env.FORMATX_TEST_URL||'https://formatxsuite.com/';
const OUT=process.env.FORMATX_SEMANTIC_EVIDENCE_DIR||'artifacts/r522-semantic-mag';
const CANVAS='#hero .fx-crystal-organism-r326-canvas';
const STAGE='#hero .fx-crystal-organism-r326-stage';
const ASK='#hero .fx-reference-ask';
const PAUSE='#hero .fx-reference-pause';
fs.mkdirSync(OUT,{recursive:true});
const writeJson=(name,value)=>fs.writeFileSync(path.join(OUT,name),JSON.stringify(value,null,2)+'\n');
function testUrl(key,value){const url=new URL(TEST_URL);url.searchParams.set(key,value);return url.href;}
async function snapshot(page){return page.evaluate(({CANVAS,STAGE,ASK,PAUSE})=>{const root=document.documentElement,canvas=document.querySelector(CANVAS),cs=canvas?getComputedStyle(canvas):null,box=canvas?.getBoundingClientRect(),header=document.querySelector('.topbar .fx-reference-mag-button'),ask=document.querySelector(ASK);const isVisible=el=>{if(!el)return false;const s=getComputedStyle(el),r=el.getBoundingClientRect();return s.display!=='none'&&s.visibility!=='hidden'&&Number(s.opacity||1)>.2&&r.width>0&&r.height>0;};return{at:performance.now(),crystal:root.dataset.fxCrystalOrganismR326||'',shapeSync:root.dataset.fxMagShapeSyncR476||'',motionContract:root.dataset.fxPrimaryMagMotionContractR528||'',life:root.dataset.fxPrimaryMagLifeR482||root.dataset.fxMiniMagLifeR479||'',lifeContract:root.dataset.fxPrimaryMagLifeContractR482||'',renderer:root.dataset.fxCoreRenderer||'',scheduler:root.dataset.fxCoreScheduler||'',idle:root.dataset.fxCoreIdleRenderR441||'',canvasCount:document.querySelectorAll(CANVAS).length,stageCount:document.querySelectorAll(STAGE).length,manualPauseCount:document.querySelectorAll(PAUSE).length,canvas:{width:box?.width||0,height:box?.height||0,display:cs?.display||'',visibility:cs?.visibility||'',opacity:Number(cs?.opacity||0),animation:cs?.animationName||'',playState:cs?.animationPlayState||''},header:{visible:isVisible(header)},ask:{visible:isVisible(ask)},balanceHref:document.querySelector('link[data-fx-mag-living-balance-r481]')?.href||'',overflow:Math.max(document.documentElement.scrollWidth,document.body.scrollWidth)-innerWidth};},{CANVAS,STAGE,ASK,PAUSE});}
async function animations(page){return page.evaluate(sel=>(document.querySelector(sel)?.getAnimations?.()||[]).map((a,index)=>({index,name:String(a.animationName||''),time:typeof a.currentTime==='number'?a.currentTime:null,state:String(a.playState||''),pending:Boolean(a.pending)})),CANVAS);}
const names=items=>items.map(x=>x.name);
function maxDelta(a,b){return Math.max(0,...b.map(item=>{const prev=a.find(x=>x.index===item.index&&x.name===item.name);return typeof item.time==='number'&&typeof prev?.time==='number'?Math.abs(item.time-prev.time):0;}));}
function semanticReady(s){return s.crystal==='ready'&&s.renderer==='single-webgl-crystal-organism-r326'&&s.canvasCount===1&&s.stageCount===1&&s.canvas.width>120&&s.canvas.height>180&&s.canvas.display!=='none'&&s.canvas.visibility!=='hidden'&&s.canvas.opacity>.2&&s.balanceHref.includes('/scifi-ui/styles/formatx-mag-living-balance-r481.css')&&s.scheduler==='interaction-bursts-idle-zero-frame-r441'&&s.header.visible&&s.ask.visible&&s.manualPauseCount===0&&s.overflow<=2;}
async function waitReady(page,name){await page.waitForTimeout(2500);let s=await snapshot(page);const deadline=Date.now()+20000;while(!semanticReady(s)&&Date.now()<deadline){await page.waitForTimeout(250);s=await snapshot(page);}console.log('R528_MAG_DUMP',name,JSON.stringify(s));assert.ok(semanticReady(s),`${name}: living MAG prerequisites absent ${JSON.stringify(s)}`);assert.match(s.shapeSync,/^ready-r\d+$/,`${name}: shape sync not ready`);assert.match(s.motionContract,/living-core-normal-continuous-reduced-background-safe/,`${name}: R528 motion contract missing`);assert.notEqual(s.canvas.animation,'none',`${name}: MAG animation unavailable`);return s;}
async function verifyNormal(browser,name,viewport,mobile){const context=await browser.newContext({viewport,isMobile:mobile,hasTouch:mobile,deviceScaleFactor:mobile?2:1,locale:'hu-HU',colorScheme:'dark',reducedMotion:'no-preference'});const page=await context.newPage(),errors=[],failed=[];page.on('pageerror',e=>errors.push(String(e)));page.on('console',m=>{const t=m.text();if(m.type()==='error'&&!/favicon|WebGL|WebGPU|GPU/i.test(t))errors.push(t);});page.on('requestfailed',r=>{if(!/cloudflareinsights|favicon/i.test(r.url()))failed.push(`${r.method()} ${r.url()} ${r.failure()?.errorText||''}`.trim());});try{await page.goto(testUrl('r528_semantic',`${name}-${Date.now()}`),{waitUntil:'domcontentloaded',timeout:30000});const state=await waitReady(page,name);if(mobile)assert.match(state.canvas.animation,/fx-primary-mag-mobile-heart-r\d+/,`${name}: mobile animation family`);else assert.match(state.canvas.animation,/fx-primary-mag-living-desktop-r\d+/,`${name}: desktop animation family`);const a0=await animations(page);await page.waitForTimeout(350);const a1=await animations(page);assert.ok(a0.length>0&&a1.length===a0.length,`${name}: animation set unavailable`);assert.deepEqual(names(a1),names(a0),`${name}: animation identity changed`);const advance=maxDelta(a0,a1);assert.ok(advance>16,`${name}: living MAG motion did not progress (${advance}ms)`);assert.equal(await page.locator(PAUSE).count(),0,`${name}: obsolete manual PAUSE control returned`);const ask=page.locator(ASK).first(),box=await ask.boundingBox();assert.ok(box&&box.width>=44&&box.height>=44,`${name}: ASK hit target invalid`);await ask.click();await page.waitForTimeout(120);const after=await snapshot(page);assert.equal(after.canvasCount,1,`${name}: ASK duplicated canvas`);assert.equal(after.stageCount,1,`${name}: ASK duplicated stage`);assert.equal(errors.length,0,`${name}: errors ${errors.join(' | ')}`);assert.equal(failed.length,0,`${name}: request failures ${failed.join(' | ')}`);return{name,viewport,state,motionAdvance:advance,ask:{width:box.width,height:box.height}};}finally{await context.close();}}
async function verifyFallback(browser){const context=await browser.newContext({viewport:{width:390,height:844},isMobile:true,hasTouch:true,locale:'hu-HU'});await context.addInitScript(()=>{const original=HTMLCanvasElement.prototype.getContext;HTMLCanvasElement.prototype.getContext=function(type,...args){if(['webgl','webgl2','experimental-webgl'].includes(type))return null;return original.call(this,type,...args);};});const page=await context.newPage(),errors=[];page.on('pageerror',e=>errors.push(String(e)));try{await page.goto(testUrl('r528_fallback',String(Date.now())),{waitUntil:'domcontentloaded',timeout:30000});await page.waitForTimeout(2500);const s=await page.evaluate(({ASK,PAUSE})=>{const ask=document.querySelector(ASK);const vis=el=>{if(!el)return false;const x=getComputedStyle(el),r=el.getBoundingClientRect();return x.display!=='none'&&x.visibility!=='hidden'&&r.width>0&&r.height>0;};return{hero:Boolean(document.querySelector('#hero')),lead:(document.querySelector('#hero .hero-lead')?.textContent||'').trim().length,live:Boolean(document.querySelector('#live-os,#live-os-overview,[data-fx-live-os]')),proof:Boolean(document.querySelector('[data-fx-award-proof],.fx-proof-grid')),ask:vis(ask),pauseCount:document.querySelectorAll(PAUSE).length,overflow:Math.max(document.documentElement.scrollWidth,document.body.scrollWidth)-innerWidth};},{ASK,PAUSE});assert.ok(s.hero&&s.lead>40&&s.live&&s.proof,`fallback content lost ${JSON.stringify(s)}`);assert.equal(s.pauseCount,0,'fallback manual PAUSE returned');assert.ok(s.overflow<=2,`fallback overflow ${s.overflow}`);assert.equal(errors.length,0,`fallback errors ${errors.join(' | ')}`);return s;}finally{await context.close();}}
async function verifyReduced(browser){const context=await browser.newContext({viewport:{width:390,height:844},isMobile:true,hasTouch:true,reducedMotion:'reduce',locale:'hu-HU'});const page=await context.newPage();try{await page.goto(testUrl('r528_reduced',String(Date.now())),{waitUntil:'domcontentloaded',timeout:30000});await page.waitForTimeout(4000);const s=await page.evaluate(({ASK,PAUSE})=>{const root=document.documentElement,ask=document.querySelector(ASK),core=document.querySelector('.topbar .fx-reference-mag-button');const vis=el=>{if(!el)return false;const x=getComputedStyle(el),r=el.getBoundingClientRect();return x.display!=='none'&&x.visibility!=='hidden'&&Number(x.opacity||1)>.2&&r.width>0&&r.height>0;};return{scheduler:root.dataset.fxP0MotionSchedulerR490||'',hero:Boolean(document.querySelector('#hero')),lead:(document.querySelector('#hero .hero-lead')?.textContent||'').trim().length,coreVisible:vis(core),askExists:Boolean(ask),pauseCount:document.querySelectorAll(PAUSE).length,overflow:Math.max(document.documentElement.scrollWidth,document.body.scrollWidth)-innerWidth};},{ASK,PAUSE});assert.ok(s.hero&&s.lead>40&&s.coreVisible,`reduced-motion product identity unavailable ${JSON.stringify(s)}`);assert.equal(s.pauseCount,0,'reduced-motion manual PAUSE returned');assert.match(s.scheduler,/reduced-motion-static|armed|committed/,`unexpected reduced scheduler ${s.scheduler}`);assert.ok(s.overflow<=2,`reduced overflow ${s.overflow}`);return s;}finally{await context.close();}}
(async()=>{const browser=await chromium.launch({executablePath:process.env.CHROME_BIN,headless:true,args:['--no-sandbox','--disable-dev-shm-usage','--use-angle=swiftshader','--enable-webgl','--ignore-gpu-blocklist','--enable-unsafe-swiftshader']});try{const [desktop,mobile]=await Promise.all([verifyNormal(browser,'desktop-1440x900',{width:1440,height:900},false),verifyNormal(browser,'mobile-390x844',{width:390,height:844},true)]);const fallback=await verifyFallback(browser),reducedMotion=await verifyReduced(browser);const report={auditedSha:process.env.AUDITED_SHA||'',origin:TEST_URL,contract:'r528-living-core-no-manual-pause',desktop,mobile,fallback,reducedMotion};writeJson('report.json',report);console.log('R528_SEMANTIC_MAG_PASS');console.log(JSON.stringify(report,null,2));}finally{await browser.close();}})().catch(error=>{writeJson('report-failure.json',{auditedSha:process.env.AUDITED_SHA||'',origin:TEST_URL,error:String(error?.stack||error)});console.error(error?.stack||error);process.exit(1);});
